<?php
require_once '../config/database.php';require_once '../includes/auth.php';require_role('admin');$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT g.*,CONCAT(t.surname,' ',t.name,' ',t.patronymic) curator_name,t.email curator_email FROM groups g LEFT JOIN teachers t ON t.id=g.curator_teacher_id WHERE g.id=?");$q->execute([$id]);$group=$q->fetch();if(!$group){die('Группа не найдена');}$page_title='Группа '.$group['name'];$s=$pdo->prepare("SELECT st.*,u.login,u.email user_email,(SELECT ROUND(AVG(gr.grade),2) FROM grades gr WHERE gr.student_id=st.id) avg_grade,(SELECT COALESCE(ROUND(100*SUM(a.status IN ('PRESENT','LATE'))/NULLIF(COUNT(*),0),1),0) FROM attendance a WHERE a.student_id=st.id) attendance FROM students st JOIN users u ON u.id=st.user_id WHERE st.group_id=? ORDER BY st.surname,st.name");$s->execute([$id]);$students=$s->fetchAll();$s=$pdo->prepare("SELECT l.lesson_date,l.start_time,s.name subject_name,CONCAT(t.surname,' ',t.name) teacher_name,l.classroom FROM lessons l JOIN subjects s ON s.id=l.subject_id JOIN teachers t ON t.id=l.teacher_id WHERE l.group_id=? AND l.lesson_date>=CURDATE() ORDER BY l.lesson_date,l.start_time LIMIT 12");$s->execute([$id]);$schedule=$s->fetchAll();$s=$pdo->prepare("SELECT (SELECT COALESCE(ROUND(100*SUM(a.status IN ('PRESENT','LATE'))/NULLIF(COUNT(*),0),1),0) FROM attendance a JOIN students st ON st.id=a.student_id WHERE st.group_id=?) attendance,(SELECT ROUND(AVG(gr.grade),2) FROM grades gr JOIN students st ON st.id=gr.student_id WHERE st.group_id=?) avg_grade");$s->execute([$id,$id]);$stats=$s->fetch();include '../includes/header.php';?>
<div class="cards"><div class="card"><div class="label">Студентов</div><div class="value"><?=count($students)?></div></div><div class="card"><div class="label">Посещаемость</div><div class="value"><?=$stats['attendance']?>%</div></div><div class="card"><div class="label">Средний балл</div><div class="value"><?=$stats['avg_grade']?:'—'?></div></div><div class="card"><div class="label">Курс</div><div class="value"><?=$group['course']?></div></div></div>
<div class="dashboard-grid"><div class="panel"><h2>О группе</h2><p><b>Группа:</b> <?=htmlspecialchars($group['name'])?></p><p><b>Специальность:</b> <?=htmlspecialchars($group['specialty'])?></p><p><b>Куратор:</b> <?=htmlspecialchars($group['curator_name']?:'Не назначен')?></p><p><b>Email:</b> <?=htmlspecialchars($group['curator_email']?:'—')?></p></div><div class="panel"><h2>Ближайшее расписание</h2><div class="table-wrap"><table><tr><th>Дата</th><th>Время</th><th>Предмет</th><th>Преподаватель</th><th>Каб.</th></tr><?php foreach($schedule as $r):?><tr><td><?=date('d.m.Y',strtotime($r['lesson_date']))?></td><td><?=substr($r['start_time'],0,5)?></td><td><?=htmlspecialchars($r['subject_name'])?></td><td><?=htmlspecialchars($r['teacher_name'])?></td><td><?=htmlspecialchars($r['classroom'])?></td></tr><?php endforeach;?></table></div></div></div>
<div class="panel" style="margin-top:20px"><h2>Студенты группы</h2><div class="table-wrap"><table><tr><th>№</th><th>ФИО</th><th>Логин</th><th>Email</th><th>Посещаемость</th><th>Средний балл</th></tr><?php foreach($students as $i=>$r):?><tr><td><?=$i+1?></td><td><b><?=htmlspecialchars($r['surname'].' '.$r['name'].' '.$r['patronymic'])?></b></td><td><?=htmlspecialchars($r['login'])?></td><td><?=htmlspecialchars($r['user_email'])?></td><td><?=$r['attendance']?>%</td><td><?=$r['avg_grade']?:'—'?></td></tr><?php endforeach;?></table></div></div><?php include '../includes/footer.php';?>
